app.post('/api/auth/register',authLimiter,requireDb,async(req,res,next)=>{try{const {workspaceName,fullName,email,password}=req.body||{};if(!workspaceName||!fullName||!email||!password||password.length<10)return res.status(400).json({error:'Workspace, name, email and a 10+ character password are required'});const base=slugify(workspaceName);let slug=base,i=1;while((await q('SELECT 1 FROM organizations WHERE slug=$1',[slug])).rowCount)slug=`${base}-${i++}`;const trialDays=Number(process.env.TRIAL_DAYS||14);const org=(await q(`INSERT INTO organizations(name,slug,trial_ends_at) VALUES($1,$2,NOW()+($3 * INTERVAL '1 day')) RETURNING *`,[workspaceName,slug,trialDays])).rows[0];await q(`INSERT INTO organization_settings(org_id) VALUES($1)`,[org.id]);const passwordHash=await bcrypt.hash(password,12);const user=(await q(`INSERT INTO users(org_id,email,password_hash,full_name,role) VALUES($1,$2,$3,$4,'owner') RETURNING id,org_id,email,full_name,role,token_version`,[org.id,email.toLowerCase().trim(),passwordHash,fullName.trim()])).rows[0];await audit(org.id,user.id,'workspace.created','organization',org.id,{name:workspaceName});res.status(201).json({token:signToken(user),user:{...user,org_name:org.name},org:{id:org.id,name:org.name,slug:org.slug,plan:org.plan,trial_ends_at:org.trial_ends_at}});}catch(e){next(e);}});
app.post('/api/auth/login',authLimiter,requireDb,async(req,res,next)=>{try{const {email,password,workspace,mfaCode}=req.body||{};if(!email||!password)return res.status(400).json({error:'Email and password are required'});let sql=`SELECT u.id,u.org_id,u.email,u.password_hash,u.full_name,u.role,u.status,u.token_version,o.name org_name,o.slug,o.plan,o.trial_ends_at FROM users u JOIN organizations o ON o.id=u.org_id WHERE lower(u.email)=lower($1)`;const params=[email.trim()];if(workspace){sql+=' AND lower(o.slug)=lower($2)';params.push(slugify(workspace));}sql+=' LIMIT 1';const row=(await q(sql,params)).rows[0];if(!row||!(await bcrypt.compare(password,row.password_hash)))return res.status(401).json({error:'Invalid credentials'});const method=(await q('SELECT * FROM mfa_methods WHERE user_id=$1 AND enabled=true',[row.id])).rows[0];if(method&&!mfaCode)return res.status(200).json({mfa_required:true});if(method&&!totpVerify(decrypt(method.secret_enc),mfaCode))return res.status(401).json({error:'Invalid MFA code'});await audit(row.org_id,row.id,'auth.login','user',row.id);res.json({token:signToken(row),user:{id:row.id,org_id:row.org_id,email:row.email,full_name:row.full_name,role:row.role,org_name:row.org_name},org:{id:row.org_id,name:row.org_name,slug:row.slug,plan:row.plan,trial_ends_at:row.trial_ends_at}});}catch(e){next(e);}});
