app.get('/api/documents',requireDb,auth,requireScope('documents:read'),async(req,res,next)=>{try{const limit=Math.min(Number(req.query.limit||50),200);const params=[req.user.org_id];let where='WHERE org_id=$1';if(req.query.status){params.push(req.query.status);where+=` AND status=$${params.length}`;}if(req.query.type){params.push(req.query.type);where+=` AND document_type=$${params.length}`;}if(req.query.q){params.push(`%${String(req.query.q).slice(0,80)}%`);where+=` AND original_name ILIKE $${params.length}`;}params.push(limit);const rows=await q(`SELECT id,name,original_name,mime_type,size_bytes,status,document_type,confidence,risk_level,error_message,pages,validation_status,validation_errors,extraction_mode,created_at,processed_at,extracted_data FROM documents ${where} ORDER BY created_at DESC LIMIT $${params.length}`,params);res.json({documents:rows.rows});}catch(e){next(e);}});
app.post('/api/documents/upload',uploadLimiter,requireDb,auth,requireRole('member'),requireScope('documents:write'),upload.array('files',MAX_BATCH),async(req,res,next)=>{const created=[];try{await enforceTrial(req.user.org_id);if(!req.files?.length)return res.status(400).json({error:'No supported files uploaded'});for(const file of req.files){if(!fileMagicValid(file)){try{fs.unlinkSync(file.path)}catch(_){ }throw Object.assign(new Error('File content does not match its declared type'),{statusCode:400});}await enforceUsage(req.user.org_id,file.size);const digest=hash(fs.readFileSync(file.path));const objectKey=`${req.user.org_id}/${new Date().toISOString().slice(0,10)}/${crypto.randomUUID()}-${sanitizeFilename(file.originalname)}`;const stored=await storagePut(file.path,objectKey,file.mimetype);if(storageMode==='s3')try{fs.unlinkSync(file.path)}catch(_){}const row=(await q(`INSERT INTO documents(org_id,uploaded_by,name,original_name,mime_type,size_bytes,storage_key,storage_mode,sha256,checksum,status,document_type) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9,$9,'queued',$10) RETURNING id,original_name,status`,[req.user.org_id,req.user.id,file.filename,sanitizeFilename(file.originalname),file.mimetype,file.size,stored.key,stored.mode,digest,req.body.documentType||'unknown'])).rows[0];await audit(req.user.org_id,req.user.id,'document.uploaded','document',row.id,{name:row.original_name,size_bytes:file.size,sha256:digest});await createJob(req.user.org_id,'document.process',{documentId:row.id});created.push(row);}res.status(201).json({documents:created});}catch(e){for(const file of req.files||[]){try{if(storageMode==='local')fs.unlinkSync(file.path)}catch(_){}}next(e);}});
app.get('/api/documents/:id',requireDb,auth,requireScope('documents:read'),async(req,res,next)=>{try{const row=(await q('SELECT * FROM documents WHERE id=$1 AND org_id=$2',[req.params.id,req.user.org_id])).rows[0];if(!row)return res.status(404).json({error:'Document not found'});res.json({document:row});}catch(e){next(e);}});
app.get('/api/documents/:id/download',requireDb,auth,requireScope('documents:read'),async(req,res,next)=>{try{const row=(await q('SELECT * FROM documents WHERE id=$1 AND org_id=$2',[req.params.id,req.user.org_id])).rows[0];if(!row)return res.status(404).json({error:'Document not found'});const got=await storageGet(row.storage_key);res.setHeader('Content-Type',got.contentType||row.mime_type);res.setHeader('Content-Disposition',`attachment; filename*=UTF-8''${encodeURIComponent(row.original_name)}`);got.stream.pipe(res);}catch(e){next(e);}});
app.delete('/api/documents/:id',requireDb,auth,requireRole('admin'),async(req,res,next)=>{try{const row=(await q('DELETE FROM documents WHERE id=$1 AND org_id=$2 RETURNING *',[req.params.id,req.user.org_id])).rows[0];if(!row)return res.status(404).json({error:'Document not found'});await storageDelete(row.storage_key);await audit(req.user.org_id,req.user.id,'document.deleted','document',row.id,{original_name:row.original_name});res.json({ok:true});}catch(e){next(e);}});
app.get('/api/export/documents.csv',requireDb,auth,requireRole('admin'),requireScope('exports:read'),async(req,res,next)=>{try{const rows=(await q(`SELECT original_name,document_type,status,confidence,risk_level,pages,created_at,processed_at,extracted_data FROM documents WHERE org_id=$1 ORDER BY created_at DESC`,[req.user.org_id])).rows;const csv=[['original_name','document_type','status','confidence','risk_level','pages','created_at','processed_at','extracted_data'].join(','),...rows.map(r=>[r.original_name,r.document_type,r.status,r.confidence,r.risk_level,r.pages,r.created_at?.toISOString?.()||r.created_at,r.processed_at?.toISOString?.()||r.processed_at,JSON.stringify(r.extracted_data)].map(csvEscape).join(','))].join('\n');res.setHeader('content-type','text/csv; charset=utf-8');res.setHeader('content-disposition','attachment; filename="docflow-documents.csv"');res.send(csv);}catch(e){next(e);}});

app.get('/api/approvals',requireDb,auth,requireScope('approvals:read'),async(req,res,next)=>{try{const rows=await q(`SELECT a.*,d.original_name,d.document_type,d.extracted_data,u.full_name requested_by_name FROM approvals a JOIN documents d ON d.id=a.document_id LEFT JOIN users u ON u.id=a.requested_by WHERE a.org_id=$1 ORDER BY a.created_at DESC LIMIT 200`,[req.user.org_id]);res.json({approvals:rows.rows});}catch(e){next(e);}});
app.post('/api/approvals/:id/decision',requireDb,auth,requireRole('admin'),async(req,res,next)=>{try{const status=req.body?.status;if(!['approved','rejected'].includes(status))return res.status(400).json({error:'Decision must be approved or rejected'});const existing=(await q("SELECT * FROM approvals WHERE id=$1 AND org_id=$2 AND status='pending'",[req.params.id,req.user.org_id])).rows[0];if(!existing)return res.status(404).json({error:'Approval not found or already decided'});if(existing.approver_role==='owner'&&req.user.role!=='owner')return res.status(403).json({error:'Owner approval is required'});const row=(await q(`UPDATE approvals SET status=$1,decided_by=$2,decided_at=NOW(),note=$3 WHERE id=$4 AND org_id=$5 AND status='pending' RETURNING *`,[status,req.user.id,req.body.note||null,req.params.id,req.user.org_id])).rows[0];await audit(req.user.org_id,req.user.id,`approval.${status}`,'approval',row.id,{document_id:row.document_id,note:req.body.note||null});if(row.workflow_id){const run=(await q(`SELECT id FROM workflow_runs WHERE workflow_id=$1 AND document_id=$2 AND org_id=$3 AND status='waiting_approval' ORDER BY created_at DESC LIMIT 1`,[row.workflow_id,row.document_id,req.user.org_id])).rows[0];if(run)await createJob(req.user.org_id,'workflow.resume',{runId:run.id,approved:status==='approved'});}res.json({approval:row});}catch(e){next(e);}});

app.get('/api/workflows',requireDb,auth,requireScope('workflows:read'),async(req,res,next)=>{try{const rows=await q('SELECT * FROM workflows WHERE org_id=$1 ORDER BY created_at DESC',[req.user.org_id]);res.json({workflows:rows.rows});}catch(e){next(e);}});
app.post('/api/workflows',requireDb,auth,requireRole('admin'),async(req,res,next)=>{try{const {name,description,triggerType,definition,enabled}=req.body||{};if(!name||!triggerType)return res.status(400).json({error:'Name and trigger type are required'});if(!['document_processed','document.processed'].includes(triggerType))return res.status(400).json({error:'Unsupported trigger type'});const safeDef=jsonSafe(definition||{});if(safeDef.webhook_url)safeDef.webhook_url=validateWebhookUrl(safeDef.webhook_url);if(safeDef.webhook_secret)safeDef.webhook_secret=encrypt(safeDef.webhook_secret);const row=(await q(`INSERT INTO workflows(org_id,name,description,trigger_type,definition,enabled,created_by) VALUES($1,$2,$3,$4,$5,$6,$7) RETURNING *`,[req.user.org_id,String(name).slice(0,120),description||null,triggerType,safeDef,enabled!==false,req.user.id])).rows[0];await audit(req.user.org_id,req.user.id,'workflow.created','workflow',row.id,{name});res.status(201).json({workflow:row});}catch(e){next(e);}});
app.patch('/api/workflows/:id',requireDb,auth,requireRole('admin'),async(req,res,next)=>{try{const def=req.body.definition?jsonSafe(req.body.definition):null;if(def?.webhook_url)def.webhook_url=validateWebhookUrl(def.webhook_url);if(def?.webhook_secret)def.webhook_secret=encrypt(def.webhook_secret);const row=(await q(`UPDATE workflows SET name=COALESCE($1,name),description=COALESCE($2,description),enabled=COALESCE($3,enabled),definition=COALESCE($4,definition),updated_at=NOW() WHERE id=$5 AND org_id=$6 RETURNING *`,[req.body.name||null,req.body.description||null,typeof req.body.enabled==='boolean'?req.body.enabled:null,def,req.params.id,req.user.org_id])).rows[0];if(!row)return res.status(404).json({error:'Workflow not found'});await audit(req.user.org_id,req.user.id,'workflow.updated','workflow',row.id);res.json({workflow:row});}catch(e){next(e);}});
