app.get('/api/team',requireDb,auth,requireRole('admin'),async(req,res,next)=>{try{const [users,invites]=await Promise.all([q(`SELECT id,email,full_name,role,status,created_at FROM users WHERE org_id=$1 ORDER BY created_at`,[req.user.org_id]),q(`SELECT id,email,role,status,expires_at,created_at FROM invites WHERE org_id=$1 ORDER BY created_at DESC LIMIT 100`,[req.user.org_id])]);res.json({users:users.rows,invites:invites.rows});}catch(e){next(e);}});
app.post('/api/team/invites',requireDb,auth,requireRole('admin'),async(req,res,next)=>{try{const email=String(req.body?.email||'').trim().toLowerCase();const role=['viewer','member','admin'].includes(req.body?.role)?req.body.role:'member';if(!email)return res.status(400).json({error:'Invite email required'});const raw=randomToken(24);const invite=(await q(`INSERT INTO invites(org_id,email,role,token_hash,expires_at,invited_by) VALUES($1,$2,$3,$4,NOW()+INTERVAL '7 days',$5) RETURNING id,email,role,expires_at`,[req.user.org_id,email,role,hash(raw),req.user.id])).rows[0];const link=`${process.env.APP_BASE_URL||'http://localhost:3000'}/?invite=${raw}`;await sendMail(email,`Invitation to ${req.user.org_name} on ${APP_NAME}`,`You have been invited to ${req.user.org_name}. Accept: ${link}`);await audit(req.user.org_id,req.user.id,'team.invite_created','invite',invite.id,{email,role});res.status(201).json({invite,acceptToken:raw});}catch(e){next(e);}});
app.post('/api/team/invites/accept',requireDb,async(req,res,next)=>{try{const {token,fullName,password}=req.body||{};if(!token||!fullName||!password||password.length<10)return res.status(400).json({error:'Invitation, name and 10+ character password are required'});const inv=(await q(`SELECT * FROM invites WHERE token_hash=$1 AND status='pending' AND expires_at>NOW()`,[hash(token)])).rows[0];if(!inv)return res.status(400).json({error:'Invitation is invalid or expired'});const exists=await q('SELECT id FROM users WHERE org_id=$1 AND lower(email)=lower($2)',[inv.org_id,inv.email]);if(exists.rowCount)return res.status(409).json({error:'An account already exists for this email'});const user=(await q(`INSERT INTO users(org_id,email,password_hash,full_name,role) VALUES($1,$2,$3,$4,$5) RETURNING id,org_id,email,full_name,role,token_version`,[inv.org_id,inv.email,await bcrypt.hash(password,12),fullName.trim(),inv.role])).rows[0];await q(`UPDATE invites SET status='accepted' WHERE id=$1`,[inv.id]);await audit(inv.org_id,user.id,'team.invite_accepted','invite',inv.id,{email:user.email});const org=(await q('SELECT * FROM organizations WHERE id=$1',[inv.org_id])).rows[0];res.status(201).json({token:signToken(user),user:{...user,org_name:org.name},org});}catch(e){next(e);}});
app.patch('/api/team/users/:id',requireDb,auth,requireRole('admin'),async(req,res,next)=>{try{const target=(await q('SELECT id,role,status FROM users WHERE id=$1 AND org_id=$2',[req.params.id,req.user.org_id])).rows[0];if(!target)return res.status(404).json({error:'User not found'});if(target.role==='owner'&&req.user.role!=='owner')return res.status(403).json({error:'Only the workspace owner can modify the owner account'});if(req.params.id===req.user.id&&req.body?.status==='suspended')return res.status(400).json({error:'You cannot suspend your own account'});if(req.body?.role==='owner')return res.status(400).json({error:'Owner transfer is not supported through this endpoint'});const role=['viewer','member','admin'].includes(req.body?.role)?req.body.role:null;const status=['active','suspended'].includes(req.body?.status)?req.body.status:null;const row=(await q(`UPDATE users SET role=COALESCE($1,role),status=COALESCE($2,status),token_version=CASE WHEN $2='suspended' THEN token_version+1 ELSE token_version END WHERE id=$3 AND org_id=$4 RETURNING id,email,full_name,role,status`,[role,status,req.params.id,req.user.org_id])).rows[0];await audit(req.user.org_id,req.user.id,'team.user_updated','user',row.id,{role,status});res.json({user:row});}catch(e){next(e);}});

