app.get('/api/enterprise/readiness',requireDb,auth,requireRole('admin'),async(req,res,next)=>{try{const controls={tenant_isolation:true,rbac:true,audit:true,approval_gates:true,jwt_sessions:true,rate_limiting:true,security_headers:true,encrypted_secrets:!!ENCRYPTION_KEY,durable_object_storage:storageMode==='s3',oidc_sso:!!(process.env.OIDC_ISSUER_URL&&process.env.OIDC_CLIENT_ID&&process.env.OIDC_CLIENT_SECRET),scim:!!process.env.SCIM_TOKEN_SECRET,document_validation:true,document_versions:true,usage_controls:true,backup_restore:'external',central_monitoring:'external',penetration_test:'external',formal_compliance:'external'};res.json({version:VERSION,controls});}catch(e){next(e);}});

app.post('/api/oidc/start',requireDb,auth,requireRole('admin'),async(req,res,next)=>{try{if(!process.env.OIDC_ISSUER_URL||!process.env.OIDC_CLIENT_ID||!process.env.OIDC_CLIENT_SECRET)return res.status(503).json({error:'OIDC is not configured'});const state=randomToken(24);const nonce=randomToken(24);await q('INSERT INTO oidc_states(org_id,state_hash,nonce) VALUES($1,$2,$3)',[req.user.org_id,hash(state),nonce]);const discovery=await (await fetch(`${process.env.OIDC_ISSUER_URL.replace(/\/$/,'')}/.well-known/openid-configuration`)).json();const redirect=process.env.OIDC_REDIRECT_URI||`${process.env.APP_BASE_URL||'http://localhost:3000'}/api/oidc/callback`;const url=new URL(discovery.authorization_endpoint);url.searchParams.set('client_id',process.env.OIDC_CLIENT_ID);url.searchParams.set('response_type','code');url.searchParams.set('scope','openid profile email');url.searchParams.set('redirect_uri',redirect);url.searchParams.set('state',state);url.searchParams.set('nonce',nonce);res.json({url:url.toString()});}catch(e){next(e);}});
app.post('/api/auth/sso/exchange',requireDb,async(req,res,next)=>{try{const code=String(req.body?.code||'');if(!code)return res.status(400).json({error:'SSO exchange code required'});const row=(await q('SELECT s.*,u.id user_id,u.org_id,u.email,u.full_name,u.role,u.token_version,o.name org_name,o.slug,o.plan,o.trial_ends_at FROM sso_codes s JOIN users u ON u.id=s.user_id JOIN organizations o ON o.id=s.org_id WHERE s.code_hash=$1 AND s.used_at IS NULL AND s.expires_at>NOW()',[hash(code)])).rows[0];if(!row)return res.status(401).json({error:'SSO code expired or invalid'});await q('UPDATE sso_codes SET used_at=NOW() WHERE id=$1',[row.id]);res.json({token:signToken(row,{sso:true}),user:{id:row.user_id,org_id:row.org_id,email:row.email,full_name:row.full_name,role:row.role,org_name:row.org_name},org:{id:row.org_id,name:row.org_name,slug:row.slug,plan:row.plan,trial_ends_at:row.trial_ends_at}});}catch(e){next(e);}});
app.post('/api/oidc/start-public',requireDb,async(req,res,next)=>{try{if(!process.env.OIDC_ISSUER_URL||!process.env.OIDC_CLIENT_ID||!process.env.OIDC_CLIENT_SECRET)return res.status(503).json({error:'OIDC is not configured'});const workspace=slugify(req.body?.workspace||'');if(!workspace)return res.status(400).json({error:'Workspace slug is required'});const org=(await q('SELECT id,slug FROM organizations WHERE lower(slug)=lower($1)',[workspace])).rows[0];if(!org)return res.status(404).json({error:'Workspace not found'});const state=randomToken(24);const nonce=randomToken(24);await q('INSERT INTO oidc_states(org_id,state_hash,nonce) VALUES($1,$2,$3)',[org.id,hash(state),nonce]);const discovery=await (await fetch(`${process.env.OIDC_ISSUER_URL.replace(/\/$/,'')}/.well-known/openid-configuration`)).json();const redirect=process.env.OIDC_REDIRECT_URI||`${process.env.APP_BASE_URL||'http://localhost:3000'}/api/oidc/callback`;const url=new URL(discovery.authorization_endpoint);url.searchParams.set('client_id',process.env.OIDC_CLIENT_ID);url.searchParams.set('response_type','code');url.searchParams.set('scope','openid profile email');url.searchParams.set('redirect_uri',redirect);url.searchParams.set('state',state);url.searchParams.set('nonce',nonce);res.json({url:url.toString()});}catch(e){next(e);}});
app.get('/api/oidc/callback',requireDb,async(req,res)=>{try{const row=(await q('SELECT * FROM oidc_states WHERE state_hash=$1 AND created_at>NOW()-INTERVAL \'10 minutes\'',[hash(req.query.state||'')])).rows[0];if(!row)return res.status(400).send('Invalid or expired SSO state');const discovery=await (await fetch(`${process.env.OIDC_ISSUER_URL.replace(/\/$/,'')}/.well-known/openid-configuration`)).json();const body=new URLSearchParams({grant_type:'authorization_code',code:String(req.query.code||''),redirect_uri:process.env.OIDC_REDIRECT_URI||`${process.env.APP_BASE_URL||'http://localhost:3000'}/api/oidc/callback`,client_id:process.env.OIDC_CLIENT_ID,client_secret:process.env.OIDC_CLIENT_SECRET});const tokenRes=await fetch(discovery.token_endpoint,{method:'POST',headers:{'content-type':'application/x-www-form-urlencoded'},body});const tokens=await tokenRes.json();if(!tokenRes.ok)throw new Error(tokens.error_description||'OIDC token exchange failed');const jwks=createRemoteJWKSet(new URL(discovery.jwks_uri));const verified=await jwtVerify(tokens.id_token,jwks,{issuer:process.env.OIDC_ISSUER_URL,audience:process.env.OIDC_CLIENT_ID});if(verified.payload.nonce!==row.nonce)throw new Error('OIDC nonce mismatch');const email=String(verified.payload.email||'').toLowerCase();if(!email)throw new Error('SSO account has no email claim');const orgSettings=(await q('SELECT allowed_email_domain FROM organization_settings WHERE org_id=$1',[row.org_id])).rows[0];if(orgSettings?.allowed_email_domain&&!email.endsWith('@'+String(orgSettings.allowed_email_domain).toLowerCase().replace(/^@/,'')))throw new Error('SSO email domain is not allowed for this workspace');const user=(await q('SELECT u.*,o.name org_name,o.slug,o.plan,o.trial_ends_at FROM users u JOIN organizations o ON o.id=u.org_id WHERE u.org_id=$1 AND lower(u.email)=lower($2)',[row.org_id,email])).rows[0];if(!user)throw new Error('SSO user is not provisioned in this workspace');await q('DELETE FROM oidc_states WHERE id=$1',[row.id]);const rawCode=randomToken(24);await q('INSERT INTO sso_codes(org_id,user_id,code_hash,expires_at) VALUES($1,$2,$3,NOW()+INTERVAL \'2 minutes\')',[row.org_id,user.id,hash(rawCode)]);const token=rawCode;res.redirect(`${process.env.APP_BASE_URL||'http://localhost:3000'}/?sso_code=${encodeURIComponent(token)}`);}catch(e){res.status(400).send(`SSO sign-in failed: ${String(e.message).replace(/[<>]/g,'')}`);}});

function scimDigest(token){return process.env.SCIM_TOKEN_SECRET?crypto.createHmac('sha256',process.env.SCIM_TOKEN_SECRET).update(String(token)).digest('hex'):hash(token);}
async function scimOrg(req){const token=String((req.headers.authorization||'').replace(/^Bearer\s+/i,''));if(!token||!process.env.SCIM_TOKEN_SECRET)return null;const row=(await q('SELECT s.*,o.slug FROM scim_tokens s JOIN organizations o ON o.id=s.org_id WHERE s.token_hash=$1 AND s.revoked=false',[scimDigest(token)])).rows[0];return row||null;}
app.post('/api/scim/token',requireDb,auth,requireRole('owner'),async(req,res,next)=>{try{const raw='scim_'+randomToken(32);await q(`INSERT INTO scim_tokens(org_id,token_hash,created_by) VALUES($1,$2,$3) ON CONFLICT(org_id) DO UPDATE SET token_hash=EXCLUDED.token_hash,created_by=EXCLUDED.created_by,created_at=NOW(),revoked=false`,[req.user.org_id,scimDigest(raw),req.user.id]);await audit(req.user.org_id,req.user.id,'scim.token_rotated','scim',req.user.org_id);res.json({token:raw,warning:'Copy this token now. It will not be shown again.'});}catch(e){next(e);}});
app.get('/scim/v2.0/:org/ServiceProviderConfig',requireDb,async(req,res)=>{const s=await scimOrg(req);if(!s||s.slug!==req.params.org)return res.status(401).json({error:'Unauthorized'});res.json({schemas:['urn:ietf:params:scim:schemas:core:2.0:ServiceProviderConfig'],patch:{supported:true},bulk:{supported:false},filter:{supported:true,maxResults:1000},changePassword:{supported:false},sort:{supported:true},etag:{supported:false},authenticationSchemes:[{type:'oauthbearertoken',name:'Bearer Token',description:'DocFlow SCIM bearer token'}]});});
app.get('/scim/v2.0/:org/ResourceTypes',requireDb,async(req,res)=>{const s=await scimOrg(req);if(!s||s.slug!==req.params.org)return res.status(401).json({error:'Unauthorized'});res.json({schemas:['urn:ietf:params:scim:api:messages:2.0:ListResponse'],totalResults:1,startIndex:1,itemsPerPage:1,Resources:[{schemas:['urn:ietf:params:scim:schemas:core:2.0:ResourceType'],id:'User',name:'User',endpoint:'/Users',schema:'urn:ietf:params:scim:schemas:core:2.0:User'}]});});
app.get('/scim/v2.0/:org/Users',requireDb,async(req,res)=>{try{const s=await scimOrg(req);if(!s||s.slug!==req.params.org)return res.status(401).json({error:'Unauthorized'});const rows=await q(`SELECT id,email,full_name,role,status FROM users WHERE org_id=$1 ORDER BY email LIMIT 1000`,[s.org_id]);res.json({schemas:['urn:ietf:params:scim:api:messages:2.0:ListResponse'],totalResults:rows.rowCount,startIndex:1,itemsPerPage:rows.rowCount,Resources:rows.rows.map(u=>({schemas:['urn:ietf:params:scim:schemas:core:2.0:User'],id:u.id,userName:u.email,displayName:u.full_name,active:u.status==='active'}))});}catch(e){res.status(500).json({error:e.message});}});
app.post('/scim/v2.0/:org/Users',requireDb,async(req,res)=>{try{const s=await scimOrg(req);if(!s||s.slug!==req.params.org)return res.status(401).json({error:'Unauthorized'});const email=String(req.body?.userName||'').toLowerCase();const fullName=req.body?.displayName||email;const existing=(await q('SELECT id FROM users WHERE org_id=$1 AND lower(email)=lower($2)',[s.org_id,email])).rows[0];if(existing)return res.status(409).json({detail:'User already exists'});const temp=randomToken(12)+'A!';const role='member';const user=(await q(`INSERT INTO users(org_id,email,password_hash,full_name,role) VALUES($1,$2,$3,$4,$5) RETURNING id,email,full_name,role,status`,[s.org_id,email,await bcrypt.hash(temp,12),fullName,role])).rows[0];await audit(s.org_id,null,'scim.user_created','user',user.id,{email});res.status(201).json({schemas:['urn:ietf:params:scim:schemas:core:2.0:User'],id:user.id,userName:user.email,displayName:user.full_name,active:true});}catch(e){res.status(500).json({error:e.message});}});
app.patch('/scim/v2.0/:org/Users/:id',requireDb,async(req,res)=>{try{const s=await scimOrg(req);if(!s||s.slug!==req.params.org)return res.status(401).json({error:'Unauthorized'});let active=null;for(const op of req.body?.Operations||[]){if(op.path==='active'||op.path==='active '){active=!!op.value;}}if(active===null&&typeof req.body?.active==='boolean')active=req.body.active;const row=(await q(`UPDATE users SET status=CASE WHEN $1::boolean THEN 'active' ELSE 'suspended' END,token_version=CASE WHEN $1::boolean THEN token_version ELSE token_version+1 END WHERE id=$2 AND org_id=$3 RETURNING id,email,full_name,status`,[active!==false,req.params.id,s.org_id])).rows[0];if(!row)return res.status(404).json({error:'User not found'});res.json({id:row.id,userName:row.email,displayName:row.full_name,active:row.status==='active'});}catch(e){res.status(500).json({error:e.message});}});
app.delete('/scim/v2.0/:org/Users/:id',requireDb,async(req,res)=>{try{const s=await scimOrg(req);if(!s||s.slug!==req.params.org)return res.status(401).json({error:'Unauthorized'});const r=await q(`UPDATE users SET status='suspended',token_version=token_version+1 WHERE id=$1 AND org_id=$2 RETURNING id`,[req.params.id,s.org_id]);if(!r.rowCount)return res.status(404).json({error:'User not found'});res.status(204).end();}catch(e){res.status(500).json({error:e.message});}});

app.post('/api/notify/test-email',requireDb,auth,requireRole('admin'),async(req,res,next)=>{try{const ok=await sendMail(req.body?.to||req.user.email,'DocFlow notification test','Your DocFlow email channel is working.');if(!ok)return res.status(503).json({error:'SMTP is not configured'});await audit(req.user.org_id,req.user.id,'notification.email_test','organization',req.user.org_id,{to:req.body?.to||req.user.email});res.json({ok:true});}catch(e){next(e);}});

function planFromPrice(priceId){
  const map={}; if(process.env.STRIPE_PRICE_STARTER)map[process.env.STRIPE_PRICE_STARTER]='starter'; if(process.env.STRIPE_PRICE_BUSINESS)map[process.env.STRIPE_PRICE_BUSINESS]='business'; if(process.env.STRIPE_PRICE_ENTERPRISE)map[process.env.STRIPE_PRICE_ENTERPRISE]='enterprise'; return map[priceId]||null;
}
async function setOrgPlan(orgId,plan){if(!['trial','starter','business','enterprise'].includes(plan))return;await q('UPDATE organizations SET plan=$1 WHERE id=$2',[plan,orgId]);await audit(orgId,null,'billing.plan_updated','organization',orgId,{plan});}
app.post('/api/billing/stripe/webhook',async(req,res)=>{try{if(!stripe||!process.env.STRIPE_WEBHOOK_SECRET)return res.status(503).send('Stripe webhook not configured');const event=stripe.webhooks.constructEvent(req.rawBody,req.headers['stripe-signature'],process.env.STRIPE_WEBHOOK_SECRET);const prior=await q('SELECT id FROM billing_events WHERE provider=$1 AND event_id=$2',['stripe',event.id]);if(prior.rowCount)return res.json({received:true,duplicate:true});const obj=event.data?.object||{};const orgId=obj.metadata?.org_id||obj.subscription_details?.metadata?.org_id||null;await q('INSERT INTO billing_events(provider,event_id,event_type,org_id,payload) VALUES($1,$2,$3,$4,$5)',['stripe',event.id,event.type,orgId,obj]);if(event.type==='checkout.session.completed'&&orgId){await setOrgPlan(orgId,obj.metadata?.plan||process.env.STRIPE_DEFAULT_PLAN||'business');}if(event.type==='customer.subscription.deleted'&&orgId){await setOrgPlan(orgId,'trial');}res.json({received:true});}catch(e){res.status(400).send('Webhook signature verification failed');}});
app.post('/api/billing/create-checkout',requireDb,auth,requireRole('owner'),async(req,res,next)=>{try{if(!stripe)return res.status(503).json({error:'Stripe billing is not configured'});const requestedPlan=['starter','business','enterprise'].includes(req.body?.plan)?req.body.plan:null;const priceByPlan={starter:process.env.STRIPE_PRICE_STARTER,business:process.env.STRIPE_PRICE_BUSINESS,enterprise:process.env.STRIPE_PRICE_ENTERPRISE};const priceId=req.body?.priceId||priceByPlan[requestedPlan]||process.env.STRIPE_DEFAULT_PRICE_ID;if(!priceId)return res.status(400).json({error:'Stripe price ID is not configured'});let customerRow=(await q('SELECT * FROM billing_customers WHERE org_id=$1',[req.user.org_id])).rows[0];let customerId=customerRow?.stripe_customer_id;if(!customerId){const customer=await stripe.customers.create({name:req.user.org_name,email:req.user.email,metadata:{org_id:req.user.org_id}});customerId=customer.id;if(customerRow)await q('UPDATE billing_customers SET stripe_customer_id=$1 WHERE org_id=$2',[customerId,req.user.org_id]);else await q('INSERT INTO billing_customers(org_id,stripe_customer_id,email) VALUES($1,$2,$3)',[req.user.org_id,customerId,req.user.email]);}const session=await stripe.checkout.sessions.create({mode:'subscription',customer:customerId,line_items:[{price:priceId,quantity:1}],success_url:`${process.env.APP_BASE_URL||'http://localhost:3000'}/?billing=success`,cancel_url:`${process.env.APP_BASE_URL||'http://localhost:3000'}/?billing=cancelled`,metadata:{org_id:req.user.org_id,plan:planFromPrice(priceId)||requestedPlan||process.env.STRIPE_DEFAULT_PLAN||'business'}});res.json({url:session.url});}catch(e){next(e);}});
app.post('/api/billing/paystack-initialize',requireDb,auth,requireRole('owner'),async(req,res,next)=>{try{if(!process.env.PAYSTACK_SECRET_KEY)return res.status(503).json({error:'Paystack billing is not configured'});const amount=Number(req.body?.amountKobo);const planCode=req.body?.planCode||process.env.PAYSTACK_PLAN_CODE;const plan=['starter','business','enterprise'].includes(req.body?.plan)?req.body.plan:null;if(!amount&&!planCode)return res.status(400).json({error:'Provide amountKobo or configure PAYSTACK_PLAN_CODE'});const payload={email:req.user.email,amount:amount?String(amount):undefined,plan:planCode||undefined,metadata:{org_id:req.user.org_id,plan:plan||process.env.PAYSTACK_DEFAULT_PLAN||'business'},callback_url:`${process.env.APP_BASE_URL||'http://localhost:3000'}/?billing=paystack`};const r=await fetch('https://api.paystack.co/transaction/initialize',{method:'POST',headers:{Authorization:`Bearer ${process.env.PAYSTACK_SECRET_KEY}`,'content-type':'application/json'},body:JSON.stringify(payload)});const body=await r.json();if(!r.ok||!body.status)return res.status(400).json({error:body.message||'Paystack initialization failed'});res.json({authorization_url:body.data.authorization_url,reference:body.data.reference});}catch(e){next(e);}});
app.post('/api/billing/paystack/webhook',async(req,res)=>{try{if(!process.env.PAYSTACK_SECRET_KEY)return res.status(503).send('Paystack webhook not configured');const signature=String(req.headers['x-paystack-signature']||'');const expected=crypto.createHmac('sha512',process.env.PAYSTACK_SECRET_KEY).update(req.rawBody||Buffer.from(JSON.stringify(req.body||{}))).digest('hex');const sigBuf=Buffer.from(signature);const expBuf=Buffer.from(expected);if(!signature||sigBuf.length!==expBuf.length||!crypto.timingSafeEqual(sigBuf,expBuf))return res.status(401).send('Invalid signature');const eventId=String(req.body?.data?.reference||req.body?.event||randomToken(12));const prior=await q('SELECT id FROM billing_events WHERE provider=$1 AND event_id=$2',['paystack',eventId]);if(prior.rowCount)return res.json({received:true,duplicate:true});const email=normalizeEmail(req.body?.data?.customer?.email||'');const metaOrgId=String(req.body?.data?.metadata?.org_id||'').trim();let org=null;if(metaOrgId) org=(await q('SELECT id FROM organizations WHERE id=$1',[metaOrgId])).rows[0];if(!org&&email) org=(await q('SELECT o.id FROM organizations o JOIN users u ON u.org_id=o.id WHERE lower(u.email)=lower($1) ORDER BY u.created_at LIMIT 1',[email])).rows[0];await q('INSERT INTO billing_events(provider,event_id,event_type,org_id,payload) VALUES($1,$2,$3,$4,$5)',['paystack',eventId,String(req.body?.event||'unknown'),org?.id||null,req.body||{}]);if(req.body?.event==='charge.success'&&org){await setOrgPlan(org.id,req.body?.data?.metadata?.plan||process.env.PAYSTACK_DEFAULT_PLAN||'business');}res.json({received:true});}catch(e){res.status(400).send('Webhook processing failed');}});
app.get('/api/usage',requireDb,auth,async(req,res,next)=>{try{const u=await usage(req.user.org_id);const org=(await q('SELECT plan FROM organizations WHERE id=$1',[req.user.org_id])).rows[0];res.json({usage:u,plan:org?.plan||'trial',limits:PLAN_LIMITS[org?.plan||'trial']||PLAN_LIMITS.trial});}catch(e){next(e);}});
app.post('/api/documents/:id/reprocess',requireDb,auth,requireRole('member'),async(req,res,next)=>{try{const row=(await q(`SELECT * FROM documents WHERE id=$1 AND org_id=$2`,[req.params.id,req.user.org_id])).rows[0];if(!row)return res.status(404).json({error:'Document not found'});await q(`UPDATE documents SET status='queued',error_message=NULL WHERE id=$1`,[row.id]);await createJob(req.user.org_id,'document.process',{documentId:row.id});await audit(req.user.org_id,req.user.id,'document.reprocess_queued','document',row.id);res.json({ok:true});}catch(e){next(e);}});
app.post('/api/documents/:id/correct',requireDb,auth,requireRole('member'),async(req,res,next)=>{try{const data=jsonSafe(req.body?.extractedData||{});const row=(await q('SELECT * FROM documents WHERE id=$1 AND org_id=$2',[req.params.id,req.user.org_id])).rows[0];if(!row)return res.status(404).json({error:'Document not found'});const version=Number((await q('SELECT COALESCE(MAX(version),0)+1 v FROM document_versions WHERE document_id=$1',[row.id])).rows[0].v);await q(`INSERT INTO document_versions(org_id,document_id,version,changed_by,extracted_data,change_note) VALUES($1,$2,$3,$4,$5,$6)`,[req.user.org_id,row.id,version,req.user.id,data,String(req.body?.note||'Manual correction').slice(0,500)]);await q(`UPDATE documents SET extracted_data=$1,validation_status='valid',validation_errors='[]'::jsonb,status='processed' WHERE id=$2`,[data,row.id]);await audit(req.user.org_id,req.user.id,'document.corrected','document',row.id,{version});res.json({ok:true,version,documentId:row.id});}catch(e){next(e);}});
app.get('/api/documents/:id/versions',requireDb,auth,requireRole('member'),async(req,res,next)=>{try{const rows=await q(`SELECT id,version,changed_by,extracted_data,change_note,created_at FROM document_versions WHERE document_id=$1 AND org_id=$2 ORDER BY version DESC`,[req.params.id,req.user.org_id]);res.json({versions:rows.rows});}catch(e){next(e);}});
app.get('/api/operations',requireDb,auth,requireRole('admin'),async(req,res,next)=>{try{const [jobs,webhooks,runs]=await Promise.all([q(`SELECT status,COUNT(*)::int count FROM job_queue WHERE org_id=$1 GROUP BY status`,[req.user.org_id]),q(`SELECT status,COUNT(*)::int count FROM webhook_deliveries WHERE org_id=$1 GROUP BY status`,[req.user.org_id]),q(`SELECT status,COUNT(*)::int count FROM workflow_runs WHERE org_id=$1 GROUP BY status`,[req.user.org_id])]);res.json({jobs:jobs.rows,webhooks:webhooks.rows,workflowRuns:runs.rows,storageMode,version:VERSION});}catch(e){next(e);}});
app.get('/api/export/documents.json',requireDb,auth,requireRole('admin'),requireScope('exports:read'),async(req,res,next)=>{try{const rows=(await q(`SELECT id,original_name,mime_type,size_bytes,status,document_type,confidence,risk_level,validation_status,validation_errors,extracted_data,created_at,processed_at FROM documents WHERE org_id=$1 ORDER BY created_at DESC`,[req.user.org_id])).rows;res.setHeader('content-type','application/json');res.setHeader('content-disposition','attachment; filename="docflow-export.json"');res.json({exported_at:new Date().toISOString(),organization_id:req.user.org_id,documents:rows});}catch(e){next(e);}});
if(process.env.METRICS_TOKEN){app.get('/metrics',(req,res)=>{if(req.headers.authorization!==`Bearer ${process.env.METRICS_TOKEN}`)return res.status(401).end();res.type('text/plain').send(`# DocFlow metrics\ndocflow_up 1\ndocflow_version{version="${VERSION}"} 1\n`);});}
