app.use(express.static(path.join(__dirname,'public')));
app.get('/app.css',(_req,res)=>res.sendFile(path.join(__dirname,'app.css')));
app.get('/styles.css',(_req,res)=>res.sendFile(path.join(__dirname,'styles.css')));
app.get('/app.js',(_req,res)=>res.sendFile(path.join(__dirname,'app.js')));
app.get('*',(req,res)=>{if(req.path.startsWith('/api/')||req.path.startsWith('/scim/'))return res.status(404).json({error:'Route not found'});res.sendFile(path.join(__dirname,'index.html'));});
app.use((err,req,res,_next)=>{console.error(`[${req.requestId}]`,err);if(err?.statusCode)return res.status(err.statusCode).json({error:err.message,requestId:req.requestId});if(err instanceof multer.MulterError)return res.status(400).json({error:err.message,requestId:req.requestId});const message=process.env.NODE_ENV==='production'?'Internal server error':err.message;res.status(500).json({error:message,requestId:req.requestId});});

(async()=>{try{await ensureSchema();app.listen(PORT,()=>console.log(`${APP_NAME} ${VERSION} listening on ${PORT}`));}catch(e){console.error(e);process.exit(1);}})();
